# IPTVPremium: Base: java.zip enviado pelo usuario; prata, abertura, historico e atualizar lista. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/AppNavigation.kt'; Binary = $false; Allowed = @('D7C69D9676AB20BBCAD34F3E23BD29BF58801F10453CF5785E4E4C60B1F2A777'); MayCreate = $false; After = 'D4C7EE071ED2A1B6DA5D6D1E80D2B7969E6BAD38E715D16FC5E5EA556E741F2F'; PayloadHash = 'D4C7EE071ED2A1B6DA5D6D1E80D2B7969E6BAD38E715D16FC5E5EA556E741F2F'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/storage/CacheRestartActivity.kt'; Binary = $false; Allowed = @('55B13193CF47F8A931F8C5DF9F27B7BF225EFF56D08B198CEB9790250FBFC077'); MayCreate = $false; After = '486D4B2A13674E2404457C6F8FB7DCDFE2D5FA6C8173F40C2BCE52ECEBB11754'; PayloadHash = '486D4B2A13674E2404457C6F8FB7DCDFE2D5FA6C8173F40C2BCE52ECEBB11754'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/history/HistorySyncSession.kt'; Binary = $false; Allowed = @('D7F915D0CE2E3D1D8CFCBA33522062A5E9BCAE41C38EEA053F6FAF2A5E89966F'); MayCreate = $false; After = '266BF70AC2EEE750340818FE1E326F7DB989F28712285763E3E15AD785611E91'; PayloadHash = '266BF70AC2EEE750340818FE1E326F7DB989F28712285763E3E15AD785611E91'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/history/SharedLibraryStore.kt'; Binary = $false; Allowed = @('FD9C5FACC64A94EFF02FD395D61BE16E603109146CFB2B074CD253A79C031C5D'); MayCreate = $false; After = 'EEC543702D75C1C199BCB32097BF1AA6CBDAEDA3FDC8F2ACB18B2E162704AA64'; PayloadHash = 'EEC543702D75C1C199BCB32097BF1AA6CBDAEDA3FDC8F2ACB18B2E162704AA64'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/history/WatchHistoryStore.kt'; Binary = $false; Allowed = @('FBA9B57AE5DC9F1F840CBBA40CCBA1518D329669EEC13E176416DA72AA3105C1'); MayCreate = $false; After = '72E621420566C5A55C2C142772E61C22CEF4715459D70FD6B7133BEC49663B93'; PayloadHash = '72E621420566C5A55C2C142772E61C22CEF4715459D70FD6B7133BEC49663B93'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieDetailsScreen.kt'; Binary = $false; Allowed = @('516718AAE280F1357166984E71E5CC6551650FBF8DC9D6E1C82115B26C116782'); MayCreate = $false; After = '51F88C9929B6FDA9FBA47FFD06D19BB4DF08839C067DD5219694C12694F84F65'; PayloadHash = '51F88C9929B6FDA9FBA47FFD06D19BB4DF08839C067DD5219694C12694F84F65'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieOpeningPolicy.kt'; Binary = $false; Allowed = @('7C34CC7D3A4C14DD578D94650C93FCAFF62AD41C07EF4E6CFEC2BBC1C648049A'); MayCreate = $false; After = 'ADB131ED73A2AEFAEABF7CF347D102DA98F997DFB69E2A6475A9FCA3EE0F826D'; PayloadHash = 'ADB131ED73A2AEFAEABF7CF347D102DA98F997DFB69E2A6475A9FCA3EE0F826D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesViewModel.kt'; Binary = $false; Allowed = @('143CE1E703888D4E3BE9D60A41D4A89264A34715149FF82B2B7C1DE9AFCA6777'); MayCreate = $false; After = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; PayloadHash = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/playlist/PlaylistListScreen.kt'; Binary = $false; Allowed = @('3005D4626726B8E0196E291F586114153F7355C71254BDFDF1C6EC9BF32E66CD'); MayCreate = $false; After = 'DEEA53F9D9070BF7A936C08ADC066303AB9BC91A40A543D990E81A1D9D8D25AC'; PayloadHash = 'DEEA53F9D9070BF7A936C08ADC066303AB9BC91A40A543D990E81A1D9D8D25AC'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MissingCastPortrait.kt'; Binary = $false; Allowed = @(); MayCreate = $true; After = 'BCB606A9F639C060D63B1C1CBACD7820FB22E2272347705413D3A93141F71B69'; PayloadHash = 'BCB606A9F639C060D63B1C1CBACD7820FB22E2272347705413D3A93141F71B69'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/cast_missing_prata.png'; Binary = $true; Allowed = @(); MayCreate = $true; After = '77E590D7B86884E80F433D08115027A44D795210E42C2FAA6C128E32A6E2B8D1'; PayloadHash = '77E590D7B86884E80F433D08115027A44D795210E42C2FAA6C128E32A6E2B8D1'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/prata-abertura-historico-listas-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: Prata no elenco, abertura 3 tentativas/15s, historico por origem concluida e Atualizar lista.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
